dtsPropsFor.JoinedCard:
/** Katılan kişi (ParticipantDto); henüz katılmadıysa `null` — kart o zaman alt satırı basmaz.
    Alt satır `locationLabel · displayName` olarak birleşir; etiket yoksa yalnız ad. */
self: {
  id?: string;
  displayName?: string;
  locationLabel?: string;
  host?: boolean;
  hasLocation?: boolean;
} | null;

dtsPropsFor.JoinFormFields:
name: string;
address: string;
/** Konum bloğunun dalı — `granted` yeşil onay kartı, `denied` elle adres girişi. */
locationState: "idle" | "granted" | "denied";
/** Konum alındıysa etiketi (ör. "Moda"); yoksa `null`. */
locationLabel: string | null;
/** Yalnız konum bloğunu meşgul eder — formun geri kalanı açık kalır. */
locationBusy?: boolean;
/** Ulaşım türü — orta nokta ve yol süresi bununla hesaplanır. */
travelMode: "WALK" | "BIKE" | "EBIKE" | "TRANSIT" | "CAR";
/** Hatanın KİMLİĞİ, metni değil — `kind` hatayı nereye koyacağını belirler:
    `geocode` adres alanının hemen altında, `tooFar` (409) CTA'nın ÜSTÜNDE kendi
    flame-wash kartında, `join` Katıl düğmesinin ALTINDA ortalanmış. Yoksa `null`. */
error: { kind: "geocode" | "tooFar" | "join"; message: string } | null;
/** Gönderim sürerken — submit butonu devre dışı. */
busy: boolean;
onNameChange: (value: string) => void;
onAddressChange: (value: string) => void;
onUseLocation: () => void;
onOtherAddress: () => void;
/** Verilirse "haritadan seç" düğmesi çıkar (harita AÇILINCA mount edilir). */
onPickOnMap?: () => void;
onTravelModeChange: (mode: "WALK" | "BIKE" | "EBIKE" | "TRANSIT" | "CAR") => void;
onSubmit: (e: React.FormEvent) => void;
